import json
import os

import jax
import jax.numpy as jnp
import numpy as np


def load(path):
    if path.endswith(".npz"):
        with np.load(path) as d:
            return {k: jnp.array(d[k]) for k in d.keys()}
    return jnp.array(np.load(path))


def save(arr, path):
    np.save(path, np.asarray(arr))


def basic_reduce(x):
    return jnp.mean(x, axis=1)


def map_square(x):
    return jax.vmap(lambda v: v ** 2)(x)


def logistic_loss(w, x, y):
    z = x @ w
    return jnp.mean(jnp.log1p(jnp.exp(-y * z)))


def grad_logistic(data):
    x, y, w = data["x"], data["y"], data["w"]
    return jax.grad(logistic_loss)(w, x, y)


def rnn_step(h, x_t, Wx, Wh, b):
    h_new = jnp.tanh(Wx @ x_t + Wh @ h + b)
    return h_new, h_new


def scan_rnn(data):
    seq, init, Wx, Wh, b = data["seq"], data["init"], data["Wx"], data["Wh"], data["b"]

    def step(h, x_t):
        return rnn_step(h, x_t, Wx, Wh, b)

    _, outs = jax.lax.scan(step, init, seq)
    return outs


def mlp_forward(X, W1, b1, W2, b2):
    h1 = jax.nn.relu(X @ W1 + b1)
    return h1 @ W2 + b2


def jit_mlp(data):
    X, W1, b1, W2, b2 = data["X"], data["W1"], data["b1"], data["W2"], data["b2"]
    fn = jax.jit(mlp_forward)
    return fn(X, W1, b1, W2, b2)


HANDLERS = {
    "basic_reduce": basic_reduce,
    "map_square": map_square,
    "grad_logistic": grad_logistic,
    "scan_rnn": scan_rnn,
    "jit_mlp": jit_mlp,
}


def main():
    with open("problem.json") as f:
        tasks = json.load(f)

    for task in tasks:
        task_id = task["id"]
        data = load(task["input"])
        result = HANDLERS[task_id](data)
        save(result, task["output"])
        print(f"{task_id}: saved to {task['output']}")


if __name__ == "__main__":
    main()
